Create a file called `course_catalog.py` and define the base class:

```python
from abc import ABC, abstractmethod
from dataclasses import dataclass, field
from datetime import datetime


class Course:
    """Base class for all TechPath courses."""

    _total_courses = 0  # Class-level counter

    def __init__(self, name, duration_months, base_fee, instructor):
        self.name = name
        self.duration_months = duration_months
        self._base_fee = base_fee
        self.instructor = instructor
        self._students = []
        self.created_at = datetime.now()
        Course._total_courses += 1

    @property
    def fee(self):
        """Fee with 18% GST."""
        return round(self._base_fee * 1.18, 2)

    @property
    def fee_per_month(self):
        return round(self.fee / self.duration_months, 2)

    @property
    def student_count(self):
        return len(self._students)

    def enroll(self, student_name):
        if student_name in self._students:
            raise ValueError(f"{student_name} is already enrolled")
        self._students.append(student_name)
        return f"{student_name} enrolled in {self.name}"

    def __str__(self):
        return f"{self.name} ({self.duration_months} months) — ₹{self.fee:,}"

    def __repr__(self):
        return f"Course(name='{self.name}', fee={self._base_fee})"

    def __eq__(self, other):
        if not isinstance(other, Course):
            return NotImplemented
        return self.name == other.name

    def __lt__(self, other):
        return self.fee < other.fee

    @classmethod
    def total_courses(cls):
        return cls._total_courses
```

