Create specialized course classes that inherit from `Course`:

```python
class OnlineCourse(Course):
    """An online course with platform and recording access."""

    def __init__(self, name, duration_months, base_fee, instructor, platform="Zoom"):
        super().__init__(name, duration_months, base_fee, instructor)
        self.platform = platform
        self.recording_access = True

    @property
    def fee(self):
        """Online courses are 20% cheaper."""
        return round(self._base_fee * 0.8 * 1.18, 2)

    def __str__(self):
        return f"[Online] {super().__str__()} via {self.platform}"


class CertificationCourse(Course):
    """A course that includes a certification exam."""

    def __init__(self, name, duration_months, base_fee, instructor, exam_fee=2000):
        super().__init__(name, duration_months, base_fee, instructor)
        self.exam_fee = exam_fee
        self.passing_marks = 70

    @property
    def fee(self):
        """Include exam fee."""
        return round((self._base_fee + self.exam_fee) * 1.18, 2)

    def __str__(self):
        return f"[Certified] {self.name} ({self.duration_months}m) — ₹{self.fee:,} (incl. exam)"


class WorkshopCourse(Course):
    """A short intensive workshop."""

    def __init__(self, name, base_fee, instructor, hours=8):
        # Workshops are always 0 months (single day/weekend)
        super().__init__(name, 0, base_fee, instructor)
        self.hours = hours

    @property
    def fee_per_month(self):
        return self.fee  # Single payment

    def __str__(self):
        return f"[Workshop] {self.name} ({self.hours}h) — ₹{self.fee:,}"
```

