Create a `Catalog` class that acts as a container with dunder methods:

```python
class Catalog:
    """A collection of courses with container behavior."""

    def __init__(self, institute_name="TechPath Institute"):
        self.institute = institute_name
        self._courses = []

    def add(self, course):
        if not isinstance(course, Course):
            raise TypeError("Can only add Course objects")
        if course in self._courses:  # Uses __eq__
            raise ValueError(f"'{course.name}' already in catalog")
        self._courses.append(course)

    def remove(self, course_name):
        for i, c in enumerate(self._courses):
            if c.name == course_name:
                return self._courses.pop(i)
        raise KeyError(f"Course '{course_name}' not found")

    def search(self, keyword):
        """Search courses by keyword in name."""
        keyword = keyword.lower()
        return [c for c in self._courses if keyword in c.name.lower()]

    def __len__(self):
        return len(self._courses)

    def __contains__(self, course_name):
        return any(c.name == course_name for c in self._courses)

    def __getitem__(self, index):
        return self._courses[index]

    def __iter__(self):
        return iter(self._courses)

    def __str__(self):
        lines = [f"\n{'=' * 55}"]
        lines.append(f"  {self.institute} — Course Catalog")
        lines.append(f"{'=' * 55}")
        for i, c in enumerate(self._courses, 1):
            lines.append(f"  {i}. {c}")
        lines.append(f"{'=' * 55}")
        lines.append(f"  Total courses: {len(self)}")
        return "\n".join(lines)
```

