Add analytics methods to the `Catalog` class:

```python
    @property
    def total_revenue_potential(self):
        """Sum of all course fees."""
        return sum(c.fee for c in self._courses)

    @property
    def cheapest(self):
        if not self._courses:
            return None
        return min(self._courses)  # Uses __lt__

    @property
    def most_expensive(self):
        if not self._courses:
            return None
        return max(self._courses)  # Uses __lt__

    def sorted_by_fee(self, reverse=False):
        """Return courses sorted by fee."""
        return sorted(self._courses, reverse=reverse)

    def by_type(self):
        """Group courses by type."""
        groups = {}
        for c in self._courses:
            type_name = type(c).__name__
            if type_name not in groups:
                groups[type_name] = []
            groups[type_name].append(c)
        return groups

    def summary(self):
        """Print a detailed summary."""
        print(f"\n--- {self.institute} Summary ---")
        print(f"Total courses: {len(self)}")
        print(f"Revenue potential: ₹{self.total_revenue_potential:,.2f}")
        print(f"Cheapest: {self.cheapest}")
        print(f"Most expensive: {self.most_expensive}")
        print(f"\nBy type:")
        for type_name, courses in self.by_type().items():
            print(f"  {type_name}: {len(courses)} course(s)")
            for c in courses:
                print(f"    - {c.name}: ₹{c.fee:,}")
